function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const normalized = normalize(raw);
const prefixes = ['tao doc', 'tao tai lieu', 'create doc'];
let body = raw;
for (const prefix of prefixes) {
  if (normalized.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let title = cleanName(source.title || source.docTitle || source.fileName || source.documentTitle || args.title || args.docTitle || args.fileName || '');
let content = source.content || source.docContent || args.content || args.docContent || '';

if (!title && body) {
  const markerMatch = body.match(/\s+(?:noi dung|nội dung|content)\s*[:=-]?\s*/i);
  if (markerMatch) {
    const idx = markerMatch.index || 0;
    title = cleanName(body.slice(0, idx));
    content = String(content || body.slice(idx + markerMatch[0].length)).trim();
  } else if (body.includes(':')) {
    const idx = body.indexOf(':');
    title = cleanName(body.slice(0, idx));
    content = String(content || body.slice(idx + 1)).trim();
  } else {
    title = cleanName(body);
  }
}

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalized,
    title,
    content: String(content || ''),
    folderId: String(source.folderId || args.folderId || '').trim(),
    hasTarget: Boolean(title),
    response: title ? '' : '📝 <b>Tao Google Doc</b>\n\nVi du: <code>tao doc Project Plan noi dung Muc tieu du an</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const created = $('Docs Create File').item.json || {};
const title = created.name || source.title || 'Không rõ tên';
const docId = created.id || '';
const link = created.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const contentLength = String(source.content || '').length;

let text = `Đã tạo Google Doc: ${title}`;
if (docId) text += `\nID: ${docId}`;
if (contentLength) text += `\nNội dung ban đầu: ${contentLength} ký tự`;
if (link) text += `\nMở tài liệu: ${link}`;

return [{ json: { chatId: source.chatId || '', text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
